window.VO = [{"id":"o01","text":"You are under digital arrest.","at":0.24,"t0":0.12,"t1":1.885},{"id":"o02","text":"Do not hang up.","at":4.17,"t0":2.085,"t1":3.165},{"id":"n01","text":"Would you fall for this?","at":6.93,"t0":3.465,"t1":4.635},{"id":"n02","text":"Then find the three mistakes on this call.","at":11.17,"t0":5.585,"t1":7.595},{"id":"o03","text":"Again. A parcel in your name.","at":15.69,"t0":7.845,"t1":9.82},{"id":"o05","text":"Your pension account is frozen.","at":22.04,"t0":11.02,"t1":13.045},{"id":"o06","text":"Declare your gold, madam.","at":26.53,"t0":13.265,"t1":14.935},{"id":"o08","text":"Tell anyone, and they are arrested too.","at":30.37,"t0":15.185,"t1":17.345},{"id":"o09","text":"That is my team.","at":38.39,"t0":19.195,"t1":20.505},{"id":"n03","text":"You just looked at your door, didn't you?","at":41.61,"t0":20.805,"t1":22.455},{"id":"n04","text":"Even though his badge can't spell police.","at":45.21,"t0":22.605,"t1":24.665},{"id":"n05","text":"And even if it could, there's no such thing as a digital arrest.","at":49.63,"t0":24.815,"t1":28.145},{"id":"n06","text":"You only know that because somebody told you.","at":56.89,"t0":28.445,"t1":30.58},{"id":"n07","text":"Nobody told your mother.","at":61.66,"t0":30.83,"t1":32.125},{"id":"n08","text":"This was never your call.","at":65.95,"t0":32.975,"t1":34.385},{"id":"n09","text":"While you hunted for mistakes, she took off her gold bangles, trying to prove she'd done nothing wrong.","at":70.67,"t0":35.335,"t1":40.53},{"id":"o12","text":"That is my team.","at":86.56,"t0":43.28,"t1":44.59},{"id":"n20","text":"You both looked at a door, and missed the last mistake.","at":89.88,"t0":44.94,"t1":47.665},{"id":"n21","text":"That wall is paper.","at":96.57,"t0":48.285,"t1":49.445},{"id":"n22","text":"Wrong door.","at":102.79,"t0":51.395,"t1":52.18},{"id":"n23","text":"He wasn't lying.","at":104.96,"t0":52.48,"t1":53.52},{"id":"n24","text":"That is his team.","at":107.28,"t0":53.64,"t1":54.68},{"id":"c01","text":"You are under digital arrest.","at":109.76,"t0":54.88,"t1":57.3},{"id":"n25","text":"Right now, they're dialling the next number.","at":115,"t0":57.5,"t1":59.66},{"id":"n26","text":"Has anybody told your mother?","at":121.92,"t0":60.96,"t1":62.52},{"id":"m03","text":"Hello?","at":128.34,"t0":64.17,"t1":64.885},{"id":"m04","text":"Hello? Can you see me?","at":130.67,"t0":65.335,"t1":66.58},{"id":"o13","text":"Yes, madam.","at":133.66,"t0":66.83,"t1":67.935},{"id":"o14","text":"We can see you.","at":136.51,"t0":68.255,"t1":69.28},{"id":"o15","text":"Do not hang up.","at":140.56,"t0":70.28,"t1":71.36},{"id":"n27","text":"Tell your mother she can.","at":143.42,"t0":71.71,"t1":73}];
